请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-005

=== 用户原始指令 (query.txt) ===
给我做个支出分类的吧，点一下能进去记账，提醒我快超支了。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个支出分类的吧，点一下能进去记账，提醒我快超支了。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "ledger://add_expense"
      }
    },
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModelSchema": {
    "finance": {
      "title": {
        "type": "string",
        "description": "卡片主标题，表示当前展示的是支出分类概览。",
        "sampleValue": "支出分类"
      },
      "statusText": {
        "type": "string",
        "description": "预算风险状态短文案，用于提示当前接近超支。",
        "sampleValue": "快超支"
      },
      "spentText": {
        "type": "string",
        "description": "本月已支出金额的展示文本。",
        "sampleValue": "¥3,680"
      },
      "spentCaption": {
        "type": "string",
        "description": "主金额下方的说明文案。",
        "sampleValue": "本月已支出"
      },
      "topCategoryText": {
        "type": "string",
        "description": "当前支出最高分类及其金额。",
        "sampleValue": "餐饮 ¥1,260"
      },
      "budgetProgressValue": {
        "type": "number",
        "description": "预算使用进度数值，按百分比刻度展示。",
        "sampleValue": 84
      },
      "budgetProgressTotal": {
        "type": "number",
        "description": "预算使用进度总量，固定为百分比总刻度。",
        "sampleValue": 100
      },
      "remainingText": {
        "type": "string",
        "description": "本月预算剩余额度展示文本。",
        "sampleValue": "剩余额度 ¥620"
      },
      "warningText": {
        "type": "string",
        "description": "接近超支时的提醒文案。",
        "sampleValue": "预算已用84%，还剩¥620"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入记账入口的短按钮文案。",
        "sampleValue": "记一笔"
      }
    }
  },
  "assetCandidates": []
}

